import React from 'react';
import { Snackbar } from '@material-ui/core';
import { Alert, AlertTitle } from '@material-ui/lab';
import { useDispatch, useSelector } from 'react-redux';
import { closeToast } from '../../../actions/admin/auth';

export default function NotificationAlertList() {
  const toastStoreData = useSelector(state => state.auth.toast);
  const dispatch = useDispatch();
  const closeAlert = () => dispatch(closeToast());

  return (
    <Snackbar
      anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      open={toastStoreData?.show}
      autoHideDuration={5000}
      onClose={() => closeAlert()}>
      {toastStoreData?.show ? (
        <Alert variant="filled" onClose={() => closeAlert()} severity={toastStoreData?.errorType}>
          {toastStoreData?.errorType && (
            <AlertTitle>
              <b>{`${toastStoreData?.errorType.charAt(0).toUpperCase()}${toastStoreData?.errorType.slice(1)}`}</b>
            </AlertTitle>
          )}
          <b>{toastStoreData?.message}</b>
        </Alert>
      ) : null}
    </Snackbar>
  );
}

